import assert from 'assert';
import {createRecoveryStore} from './recovery-store.js';
import {parseWorkingSnapshot,validateBodyRecovery,encodeWorkingFile,parseWorkingFile} from './working-draft.js';
import {example,parseDraft} from './model.js';
globalThis.crypto={randomUUID:()=>Math.random().toString()};
const map=new Map(),storage={getItem:key=>map.get(key)??null,setItem:(key,value)=>map.set(key,value),removeItem:key=>map.delete(key)};
const first=createRecoveryStore(storage,'key','project',parseWorkingSnapshot,{writer:'one',now:()=>123});
assert.equal(first.read(),null);
const project=example();project.blocks=project.blocks.filter(b=>b.type!=='return');project.name='';project.variables[0].type='invalid';
const work={project,selected:project.blocks[0].id,parametersText:'input_value : integer',variablesText:'running_total :',branch:'after'};
first.write(work);assert.equal(first.read().value.variablesText,'running_total :');
assert.throws(()=>parseDraft(JSON.stringify(project)));
assert.deepEqual(parseWorkingFile(encodeWorkingFile(work)),parseWorkingSnapshot(work));
assert.throws(()=>parseWorkingFile(JSON.stringify({format:'pgdebug-working-project',version:1,snapshot:work,password:'forbidden'})));
assert(!JSON.parse(map.get('key')).value.project.password);
console.log('PASS recovery: unfinished project/declarations round trip without becoming applicable SQL');
const second=createRecoveryStore(storage,'key','project',parseWorkingSnapshot,{writer:'two',now:()=>124});second.read();
first.write({...work,variablesText:'another edit'});
assert.throws(()=>second.write(work),/другой вкладке/);assert.throws(()=>second.clear(),/другой вкладке/);
assert.equal(second.read().value.variablesText,'another edit');second.clear();assert.equal(map.has('key'),false);
map.set('key','{broken');assert.throws(()=>first.read(),/JSON/);first.clear();
console.log('PASS recovery: stale writers/discards rejected and damaged records removable');
const body={target:{host:'127.0.0.1',port:5432,database:'demo',user:'owner',schema:'public',name:'f',signature:'integer',kind:'Функция'},definition:'CREATE FUNCTION f',body:'BEGIN RETURN ; END;'};
assert.equal(validateBodyRecovery(body).body,body.body);
assert.throws(()=>validateBodyRecovery({...body,password:'must not persist'}));
assert.throws(()=>parseWorkingSnapshot({...work,project:{...work.project,password:'must not persist'}}));
const quota=createRecoveryStore({...storage,setItem:()=>{throw Error('quota');}},'quota','body',validateBodyRecovery,{writer:'one'});quota.read();assert.throws(()=>quota.write(body),/заполнено/);
console.log('PASS recovery: credentials/unknown fields excluded, malformed body context and storage failures handled');
